module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] counter = 0;
    reg tick = 0;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            tick <= 0;
        end else begin
            if (counter == div - 1) begin
                counter <= 0;
                tick <= 1;
            end else begin
                counter <= counter + 1;
                tick <= 0;
            end
        end
    end

endmodule

