module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [31:0] counter = 0;
    reg [31:0] index = 0;
    reg [31:0] keypress_array [0:15] = {10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0, 10'b0};
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
        end else begin
            if (counter == 20) begin
                counter <= 0;
                index <= index + 1;
            end else begin
                counter <= counter + 1;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            keypress <= 10'b0;
        end else begin
            if (index == 15) begin
                keypress <= keypress_array[0];
            end else begin
                keypress <= keypress_array[index];
            end
        end
    end
endmodule

