module lookuptable #( parameter    phase_width = 4,  data_width	= 8)(
	input               [phase_width - 1 :0]  phase,
	output     reg      [data_width - 1 :0]  sin,
	output     reg      [data_width - 1 :0]  cos);
localparam [data_width - 1 :0] sin_0 = 8'b00000000;
	localparam [data_width - 1 :0] sin_1 = 8'b00000001;
	localparam [data_width - 1 :0] sin_2 = 8'b00000010;
	localparam [data_width - 1 :0] sin_3 = 8'b00000011;
	localparam [data_width - 1 :0] sin_4 = 8'b00000100;
	localparam [data_width - 1 :0] sin_5 = 8'b00000101;
	localparam [data_width - 1 :0] sin_6 = 8'b00000110;
	localparam [data_width - 1 :0] sin_7 = 8'b00000111;
	localparam [data_width - 1 :0] sin_8 = 8'b00001000;
	localparam [data_width - 1 :0] sin_9 = 8'b00001001;
	localparam [data_width - 1 :0] sin_10 = 8'b00001010;
	localparam [data_width - 1 :0] sin_11 = 8'b00001011;
	localparam [data_width - 1 :0] sin_12 = 8'b00001100;
	localparam [data_width - 1 :0] sin_13 = 8'b00001101;
	localparam [data_width - 1 :0] sin_14 = 8'b00001110;
	localparam [data_width - 1 :0] sin_15 = 8'b00001111;
	localparam [data_width - 1 :0] cos_0 = 8'b00000000;
	localparam [data_width - 1 :0] cos_1 = 8'b00000001;
	localparam [data_width - 1 :0] cos_2 = 8'b00000010;
	localparam [data_width - 1 :0] cos_3 = 8'b00000011;
	localparam [data_width - 1 :0] cos_4 = 8'b00000100;
	localparam [data_width - 1 :0] cos_5 = 8'b00000101;
	localparam [data_width - 1 :0] cos_6 = 8'b00000110;
	localparam [data_width - 1 :0] cos_7 = 8'b00000111;
	localparam [data_width - 1 :0] cos_8 = 8'b00001000;
	localparam [data_width - 1 :0] cos_9 = 8'b00001001;
	localparam [data_width - 1 :0] cos_10 = 8'b00001010;
	localparam [data_width - 1 :0] cos_11 = 8'b00001011;
	localparam [data_width - 1 :0] cos_12 = 8'b00001100;
	localparam [data_width - 1 :0] cos_13 = 8'b00001101;
	localparam [data_width - 1 :0] cos_14 = 8'b00001110;
	localparam [data_width - 1 :0] cos_15 = 8'b00001111;
	always @(*) begin
		case (phase)
			4'b0000: sin = sin_0;
			4'b0001: sin = sin_1;
			4'b0010: sin = sin_2;
			4'b0011: sin = sin_3;
			4'b0100: sin = sin_4;
			4'b0101: sin = sin_5;
			4'b0110: sin = sin_6;
			4'b0111: sin = sin_7;
			4'b1000: sin = sin_8;
			4'b1001: sin = sin_9;
			4'b1010: sin = sin_10;
			4'b1011: sin = sin_11;
			4'b1100: sin = sin_12;
			4'b1101: sin = sin_13;
			4'b1110: sin = sin_14;
			4'b1111: sin = sin_15;
			default: sin = 0;
		endcase
		case (phase)
			4'b0000: cos = cos_0;
			4'b0001: cos = cos_1;
			4'b0010: cos = cos_2;
			4'b0011: cos = cos_3;
			4'b0100: cos = cos_4;
			4'b0101: cos = cos_5;
			4'b0110: cos = cos_6;
