    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = (state == ONE);
assign m_data  = data_p1;
assign m_valid = (state == TWO);

always @(posedge clk) begin
    if (reset == 1'b1)
        begin
            data_p1 <= {N{1'b0}};
            data_p2 <= {N{1'b0}};
            state   <= ZERO;
        end
    else begin
        data_p1 <= (m_ready == 1'b1) ? s_data : data_p1;
        data_p2 <= (s_valid == 1'b1) ? data_p1 : data_p2;
        next    <= (m_ready == 1'b1) ? ONE : (s_valid == 1'b1) ? TWO : ZERO;
        state   <= next;
    end
end

endmodule

