module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state;
   reg [35:0] data0, data1;
   reg src0_rdy, src1_rdy;
   assign data0_o = state == DATA0 ? data0 : 0;
   assign data1_o = state == DATA1 ? data1 : 0;
   assign src0_rdy_o = state == DATA0 ? src0_rdy : 0;
   assign src1_rdy_o = state == DATA1 ? src1_rdy : 0;
   assign dst_rdy_o = state == DATA0 ? dst0_rdy_i : dst1_rdy_i;
   always @(posedge clk) begin
      if (clear) begin
         state <= IDLE;
         src0_rdy <= 0;
         src1_rdy <= 0;
      end else if (state == IDLE) begin
         if (src_rdy_i) begin
            if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
               state <= DATA0;
               src0_rdy <= 1;
               src1_rdy <= 0;
            end else begin
               state <= DATA1;
               src0_rdy <= 0;
               src1_rdy <= 1;
            end
         end
      end else if (state == DATA0) begin
         if (dst0_rdy_i) begin
            state <= IDLE;
            src0_rdy <= 0;
            src1_rdy <= 0;
         end
      end else if (state == DATA1) begin
         if (dst1_rdy_i) begin
            state <= IDLE;
            src0_rdy <= 0;
            src1_rdy <= 0;
         end
      end
   end
   always @(posedge clk) begin
      if (state == DATA0) begin
         if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
            data0 <= data_i;
         end
      end else if (state == DATA1) begin
         if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
            data1 <= data_i;
         end
      end
   end
endmodule

