        else if (dig[4]) begin
            deci <= 4'b0110;
            uni <= 4'b0000;
        end
        else if (dig[3]) begin
            deci <= 4'b0111;
            uni <= 4'b0000;
        end
        else if (dig[2]) begin
            deci <= 4'b1000;
            uni <= 4'b0000;
        end
        else if (dig[1]) begin
            deci <= 4'b1001;
            uni <= 4'b0000;
