module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [DW-1:0] cached_data0, cached_data1;
reg [DW-1:0] cached_addr0, cached_addr1;
reg hit0, hit1;
reg [DW-1:0] subaddr;
reg good;

assign sdram_addr = addr_req + offset;

assign data_ok = (subaddr == 0) ? 1'b1 : 1'b0;

always @* begin
    if (we) begin
        if (addr_req == cached_addr0) begin
            cached_data0 <= din;
            hit0 <= 1'b1;
        end
        if (addr_req == cached_addr1) begin
            cached_data1 <= din;
            hit1 <= 1'b1;
        end
    end
    else begin
        hit0 <= 1'b0;
        hit1 <= 1'b0;
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        addr_req <= {AW{1'b0}};
        cached_addr0 <= {DW{1'b0}};
        cached_addr1 <= {DW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= {DW{1'b0}};
        good <= 1'b0;
    end
    else if (clr) begin
        addr_req <= {AW{1'b0}};
        cached_addr0 <= {DW{1'b0}};
        cached_addr1 <= {DW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= {DW{1'b0}};
        good <= 1'b0;
    end
    else begin
        if (addr_ok) begin
            addr_req <= addr;
            subaddr <= addr_req[DW-1:0];
            if (subaddr == 0) begin
                if (hit0) begin
                    addr_req <= addr_req + 1;
                    good <= 1'b1;
                end
                else begin
                    addr_req <= addr_req + 1;
                    good <= 1'b0;
                end
            end
            else begin
                if (hit0) begin
                    addr_req <= addr_req + 1;
                    good <= 1'b1;
                end
                else begin
                    addr_req <= addr_req + 1;
                    good <= 1'b0;
                end
            end
        end
        else begin
            addr_req <= {AW{1'b0}};
            subaddr <= {DW{1'b0}};
            good <= 1'b0;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        req <= 1'b0;
    end
    else if (clr) begin
        req <= 1'b0;
    end
    else if (addr_ok) begin
        if (we) begin
            if (addr_req == cached_addr0) begin
                req <= 1'b1;
            end
            else if (addr_req == cached_addr1) begin
                req <= 1'b1;
            end
        end
        else begin
            req <= 1'b0;
        end
    end
    else begin
        req <= 1'b0;
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        dout <= {DW{1'b0}};
    end
    else if (clr) begin
        dout <= {DW{1'b0}};
    end
    else if (we) begin
        if (addr_req == cached_addr0) begin
            dout <= cached_data0;
        end
        else if (addr_req == cached_addr1) begin
            dout <= cached_data1;
        end
    end
    else begin
        dout <= {DW{1'b0}};
    end
end

