module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
reg [7:0] data;
assign io_ready = (state == 4'b0000);
assign tx = (state == 4'b0001) ? data[0] : 1'b0;
always @(posedge clock) begin
  if (reset) begin
    state <= 4'b0000;
    data <= 8'b00000000;
  end else begin
    if (tick) begin
      case (state)
      4'b0000: begin
        if (io_valid) begin
          state <= 4'b0001;
          data <= io_bits;
        end
      end
      4'b0001: begin
        if (io_valid) begin
          state <= 4'b0010;
          data <= data >> 1;
        end
      end
      4'b0010: begin
        if (io_valid) begin
          state <= 4'b0011;
          data <= data >> 1;
        end
      end
      4'b0011: begin
        if (io_valid) begin
          state <= 4'b0100;
          data <= data >> 1;
        end
      end
      4'b0100: begin
        if (io_valid) begin
          state <= 4'b0101;
          data <= data >> 1;
        end
      end
      4'b0101: begin
        if (io_valid) begin
          state <= 4'b0110;
          data <= data >> 1;
        end
      end
      4'b0110: begin
        if (io_valid) begin
          state <= 4'b0111;
          data <= data >> 1;
        end
      end
      4'b0111: begin
        if (io_valid) begin
          state <= 4'b1000;
          data <= data >> 1;
        end
      end
      4'b1000: begin
        if (io_valid) begin
          state <= 4'b1001;
          data <= data >> 1;
        end
      end
      4'b1001: begin
        if (io_valid) begin
          state <= 4'b1010;
          data <= data >> 1;
        end
      end
      4'b1010: begin
        if (io_valid) begin
          state <= 4'b1011;
          data <= data >> 1;
        end
      end
      4'b1011: begin
        if (io_valid) begin
          state <= 4'b1100;
          data <= data >> 1;
        end
      end
      4'b1100: begin
        if (io_valid) begin
          state <= 4'b1101;
          data <= data >> 1;
        end
      end
      4'b1101: begin
        if (io_valid) begin
          state <= 4'b1110;
          data <= data >> 1;
        end
      end
      4'b1110: begin
        if (io_valid) begin
          state <= 4'b1111;
          data <= data >> 1;
        end
      end
      4'b1111: begin
        if (io_valid) begin
          state <= 4'b0000;
          data <= io_bits;
        end
      end
      default: begin
        state <= 4'b0000;
        data <= 8'b00000000;
      end
      endcase
    end
  end
end
