module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [10:0] H_ACTIVE=1280;
parameter [10:0] H_FRONT=48;
parameter [10:0] H_BACK=96;
parameter [10:0] H_SYNC=24;
parameter [10:0] H_TOTAL=H_ACTIVE + H_FRONT + H_BACK + H_SYNC;
parameter [10:0] V_ACTIVE=720;
parameter [10:0] V_FRONT=10;
parameter [10:0] V_BACK=10;
parameter [10:0] V_SYNC=2;
parameter [10:0] V_TOTAL=V_ACTIVE + V_FRONT + V_BACK + V_SYNC;
reg [10:0] X;
reg [10:0] Y;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      X <= 0;
      Y <= 0;
      H_SYNC <= 1'b1;
      V_SYNC <= 1'b1;
      DISP_EN <= 1'b0;
    end else begin
      if(X == H_TOTAL - 1) begin
        X <= 0;
        if(Y == V_TOTAL - 1) begin
          Y <= 0;
        end
        else begin
          Y <= Y + 1;
        end
      end
      else begin
        X <= X + 1;
      end
      if(X == H_ACTIVE - 1) begin
        H_SYNC <= 1'b0;
      end
      else begin
        H_SYNC <= 1'b1;
      end
      if(Y == V_ACTIVE - 1) begin
        V_SYNC <= 1'b0;
      end
      else begin
        V_SYNC <= 1'b1;
      end
      if(X < H_ACTIVE && Y < V_ACTIVE) begin
        DISP_EN <= 1'b1;
      end
      else begin
        DISP_EN <= 1'b0;
      end
    end
  end
endmodule

