module rbw_check(
    input wire          clk,        
    input wire          a_rst,      
    input wire          i_rbw,      
    input wire[L:0]     i_rbw_adr,  
    input wire          rs,         
    input wire          r_ts,       
    input wire[L:0]     rs_adr,     
    input wire          ws,         
    input wire          w_ts,       
    input wire[L:0]     ws_adr,     
    output wire         o_rbw       
);
parameter L = 16;

reg  rbw;
reg  rbw_adr;
reg  rbw_ts;
reg  rbw_valid;
reg  rbw_ready;
reg  rbw_conflict;

assign o_rbw = rbw_valid & rbw_ready;

always @(posedge clk) begin
    if (a_rst) begin
        rbw <= 0;
        rbw_adr <= 0;
        rbw_ts <= 0;
        rbw_valid <= 0;
        rbw_ready <= 0;
        rbw_conflict <= 0;
    end else begin
        if (i_rbw) begin
            rbw <= 1;
            rbw_adr <= i_rbw_adr;
            rbw_ts <= r_ts;
            rbw_valid <= 1;
            rbw_ready <= 0;
            rbw_conflict <= 0;
        end else if (ws && ws_adr == rs_adr && ws_adr == rbw_adr && w_ts == rbw_ts) begin
            rbw_conflict <= 1;
            rbw_valid <= 0;
            rbw_ready <= 0;
        end else if (rbw_conflict) begin
            rbw_conflict <= 0;
            rbw_valid <= 0;
            rbw_ready <= 0;
        end else if (rbw) begin
            rbw_valid <= 1;
            rbw_ready <= 1;
        end
    end
end

endmodule

