module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
reg [OUTPUT_BITS-1:0] root_gen;
reg [OUTPUT_BITS-1:0] radicand_gen;
reg [OUTPUT_BITS-1:0] mask_gen;
reg start_gen;

genvar i;
generate
for (i=0; i<OUTPUT_BITS; i=i+1) begin : PIPELINED_SQRT
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      start_gen <= 1'b0;
      radicand_gen <= {OUTPUT_BITS{1'b0}};
      root_gen <= {OUTPUT_BITS{1'b0}};
      mask_gen <= {OUTPUT_BITS{1'b0}};
    end else begin
      if (start) begin
        start_gen <= 1'b1;
      end else begin
        start_gen <= 1'b0;
      end
      if (start_gen) begin
        radicand_gen <= radicand;
        root_gen <= {OUTPUT_BITS{1'b0}};
        mask_gen <= {OUTPUT_BITS{1'b0}};
      end else begin
        mask_gen <= radicand_gen[OUTPUT_BITS-1] ? {OUTPUT_BITS{1'b1}} : {OUTPUT_BITS{1'b0}};
        radicand_gen <= radicand_gen - mask_gen * root_gen;
        root_gen <= root_gen + mask_gen * radicand_gen;
      end
    end
  end
end
endgenerate

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    data_valid <= 1'b0;
    root <= {OUTPUT_BITS{1'b0}};
  end else begin
    data_valid <= start_gen;
    root <= root_gen;
  end
end

endmodule

