module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    always @(posedge i_clock or negedge reset) begin
        if (reset) begin
            scan_code <= 8'b0;
            counter <= 4'b0;
        end else begin
            if (counter == 4'b1111) begin
                scan_code <= scan_code;
                counter <= counter;
            end else begin
                scan_code[counter] <= i_data;
                counter <= counter + 1;
            end
        end
    end
    assign scan_ready = counter == 4'b1111;
endmodule

