module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   state;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;

assign s_ready = (state == ZERO);
assign m_data  = data_p1;
assign m_valid = (state == TWO);

always @(posedge clk) begin
    if (reset == 1'b1)
    begin
        data_p1 <= { (N){1'b0} };
        data_p2 <= { (N){1'b0} };
        state   <= ZERO;
    end
    else begin
        load_p1 <= s_valid & s_ready;
        load_p2 <= m_ready & m_valid;
        load_p1_from_p2 <= (state == ONE);
        if (load_p1_from_p2 == 1'b1)
            data_p1 <= data_p2;
        if (load_p1 == 1'b1)
            data_p2 <= s_data;
        if (load_p2 == 1'b1)
            state <= state + 1;
        else if (load_p1 == 1'b0)
            state <= ZERO;
    end
end

endmodule

