module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
); 

parameter [31:0] PERIOD=8;
reg [31:0] duty_reg;
reg [31:0] counter;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      duty_reg <= duty;
      counter <= 0;
      pwm_out <= 1'b0;
    end else begin
      if((counter < duty_reg)) begin
        pwm_out <= 1'b1;
      end
      else begin
        pwm_out <= 1'b0;
      end
      if((counter == (PERIOD - 1))) begin
        counter <= 0;
        duty_reg <= duty;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

