module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
wire [3:0] state_size;
  wire [1:0] state_source;
  wire do_enq;
  wire do_deq;
  wire maybe_full;
  assign io_enq_ready = do_enq;
  assign io_deq_valid = do_deq;
  assign io_deq_bits_tl_state_size = state_size;
  assign io_deq_bits_tl_state_source = state_source;
  assign do_enq = io_enq_valid & io_enq_ready;
  assign do_deq = io_deq_valid & io_deq_ready;
  assign maybe_full = io_enq_valid & io_enq_ready;
  always @(posedge clock) begin
    if (reset) begin
      state_size <= 4'h0;
      state_source <= 2'h0;
    end else begin
      if (do_enq) begin
        if (io_enq_bits_tl_state_size > state_size) begin
          state_size <= io_enq_bits_tl_state_size;
        end
      end
      if (do_deq) begin
        if (io_deq_bits_tl_state_size < state_size) begin
          state_size <= io_deq_bits_tl_state_size;
        end
      end
      if (do_enq & do_deq) begin
        if (io_enq_bits_tl_state_size > io_deq_bits_tl_state_size) begin
          state_size <= io_enq_bits_tl_state_size;
        end
        if (io_enq_bits_tl_state_source != io_deq_bits_tl_state_source) begin
          state_source <= io_enq_bits_tl_state_source;
        end
      end
    end
  end
  always @(posedge clock) begin
    if (reset) begin
      maybe_full <= 1'b0;
    end else begin
      if (do_enq & do_deq) begin
        if (io_enq_bits_tl_state_size > io_deq_bits_tl_state_size) begin
          maybe_full <= 1'b1;
        end
        if (io_enq_bits_tl_state_size < io_deq_bits_tl_state_size) begin
          maybe_full <= 1'b0;
        end
      end
    end
  end
endmodule

