assign m_valid = (state == TWO);

always @(posedge clk) begin
    if (reset == 1'b1)
        state <= ZERO;
    else begin
        case (state)
        ZERO: begin
            if (s_valid & m_ready)
                state <= ONE;
        end
        ONE: begin
            if (s_valid & m_ready)
                state <= TWO;
            else if (s_valid & ~m_ready)
                state <= ZERO;
        end
        TWO: begin
            if (~s_valid & m_ready)
                state <= ONE;
            else if (~s_valid & ~m_ready)
                state <= ZERO;
        end
        endcase
    end
end

always @(posedge clk) begin
    if (reset == 1'b1)
        load_p1 <= 1'b0;
    else if (state == ZERO)
        load_p1 <= 1'b1;
    else if (state == ONE)
        load_p1 <= s_valid & m_ready;
    else if (state == TWO)
        load_p1 <= s_valid & ~m_ready;
end

always @(posedge clk) begin
    if (reset == 1'b1)
        load_p2 <= 1'b0;
    else if (state == ONE)
        load_p2 <= 1'b1;
    else if (state == TWO)
        load_p2 <= s_valid & m_ready;
    else if (state == ZERO)
        load_p2 <= s_valid & ~m_ready;
end

always @(posedge clk) begin
    if (reset == 1'b1)
        data_p1 <= {N{1'b0}};
    else if (load_p1)
        data_p1 <= s_data;
end

always @(posedge clk) begin
    if (reset == 1'b1)
        data_p2 <= {N{1'b0}};
    else if (load_p2)
        data_p2 <= s_data;
end

