always @(posedge clk or posedge rst) begin
	if(rst) begin
		catodo <= 0;
	end else begin
		case(q_reg[N-2:N-1])
			2'b00: catodo <= in0;
			2'b01: catodo <= in1;
			2'b10: catodo <= in2;
			2'b11: catodo <= in3;
