module mash(
input wire [63:0] din,
output wire [31:0] dout
); 

wire [31:0] even_bits;
wire [31:0] odd_bits;
  assign even_bits = din[63:32];
  assign odd_bits = din[31:0];
  genvar i;
  generate for (i=0; i <= 31; i = i + 1) begin: gen_even
    assign even_bits[i] = din[63 - i];
  end
  endgenerate
  genvar j;
  generate for (j=0; j <= 31; j = j + 1) begin: gen_odd
    assign odd_bits[j] = din[31 - j];
  end
  endgenerate
  assign dout = even_bits | odd_bits;
endmodule

