module full_adder_19(
input wire a,
input wire b,
input wire c,
output wire sum,
output wire carry
); 

assign sum = c | (a & b) | (a & ~b) | (b & ~a);
  assign carry = a & b;
endmodule

module first_counter (
clock , 
reset , 
enable , 
counter_out 
); 

input clock ;
input reset ;
input enable ;

output [3:0] counter_out ;
reg [3:0] counter_out ;

always @ (posedge clock) begin
	if (reset == 1) begin
