module ram(
  input clk,
  input enable,
  input write_enable,
  input [WIDTH-1 : 0] addr,
  input [WIDTH-1 : 0] data_in,
  output [WIDTH-1 : 0] data_out);
parameter ADDRESS_WIDTH = 16;
  parameter WIDTH = 8;
  parameter MEMORY_SIZE = 1 << ADDRESS_WIDTH;
  reg [WIDTH-1 : 0] mem [MEMORY_SIZE-1 : 0];
  integer i;
  initial begin
    $readmemh("prog_fib.list", mem);
  end
  always @* begin
    if (enable) begin
      data_out = mem[addr];
    end else begin
      data_out = 0;
    end
  end
  always @(posedge clk) begin
    if (write_enable) begin
      mem[addr] <= data_in;
    end
  end
endmodule

