module diffeq_paj_convert (Xinport, Yinport, Uinport, Aport, DXport, Xoutport, Youtport, Uoutport, CLK, reset);
    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
reg[31:0] Xinport; 
    reg[31:0] Yinport; 
    reg[31:0] Uinport; 
    reg[31:0] Aport; 
    reg[31:0] DXport; 
    reg[31:0] Xoutport; 
    reg[31:0] Youtport; 
    reg[31:0] Uoutport; 
    reg[31:0] x_var; 
    reg[31:0] y_var; 
    reg[31:0] u_var; 
    reg[31:0] temp; 
    always @(posedge CLK or posedge reset) begin
        if (reset) begin
            x_var <= 0;
            y_var <= 0;
            u_var <= 0;
        end else begin
            x_var <= x_var + DXport;
            y_var <= y_var + (x_var * Uinport);
            u_var <= (y_var - Xinport) / Yinport;
            if (x_var >= Aport) begin
                Xoutport <= x_var;
                Youtport <= y_var;
                Uoutport <= u_var;
            end
        end
    end
endmodule

