module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] cnt;
    always @(posedge clk or posedge reset)
    begin
        if(reset)
            cnt <= 0;
        else
            cnt <= cnt + 1;
    end
    always @*
    begin
        case(cnt)
            0: begin
                en <= 4'b1111;
                sseg <= hex3;
                sseg[6] <= dp[3];
            end
            1: begin
                en <= 4'b1110;
                sseg <= hex2;
                sseg[6] <= dp[2];
            end
            2: begin
                en <= 4'b1101;
                sseg <= hex1;
                sseg[6] <= dp[1];
            end
            3: begin
                en <= 4'b1011;
                sseg <= hex0;
                sseg[6] <= dp[0];
            end
            default: begin
                en <= 4'b0000;
                sseg <= 8'b00000000;
            end
        endcase
    end
endmodule

