module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires = {enable_wires[BITS - 2:0], ena};
    assign out = cnt;
    assign ovf = (cnt == 2 ** BITS - 1) ^ updown;
    genvar i;
    generate for (i = 0; i < BITS; i = i + 1) begin: gen_bit
        always @(posedge clk, posedge rst) begin
            if (rst) begin
                cnt <= 0;
            end else if (ena) begin
                if (updown) begin
                    cnt <= cnt + 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end
    endgenerate
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
		assign reg1 = binary;
		assign b = reg1[3:0];
		assign s = reg1[7:4];
		assign g = reg1[11:8];
		assign q = reg1[15:12];
		repeat (16) begin
			if (reg1[3:0] > 4) begin
				reg1[3:0] = reg1[3:0] + 3;
			end
			if (reg1[7:4] > 4) begin
				reg1[7:4] = reg1[7:4] + 3;
			end
			if (reg1[11:8] > 4) begin
				reg1[11:8] = reg1[11:8] + 3;
			end
			if (reg1[15:12] > 4) begin
				reg1[15:12] = reg1[15:12] + 3;
			end
			reg1 = reg1 >> 4;
		end
		assign b = reg1[3:0];
		assign s = reg1[7:4];
		assign g = reg1[11:8];
		assign q = reg1[15:12];
endmodule

