module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
reg [15:0] H_cnt;

wire Pout_de_w;
wire Pout_hs_w;
wire Pout_vs_w;
wire Rden_w;

always @ (posedge I_pxl_clk or negedge I_rst_n)
begin
    if (!I_rst_n)
    begin
        V_cnt <= 0;
        H_cnt <= 0;
    end
    else
    begin
        if (V_cnt == I_v_total - 1)
        begin
            V_cnt <= 0;
            H_cnt <= H_cnt + 1;
        end
        else
            V_cnt <= V_cnt + 1;
    end
end

assign Pout_de_w = (H_cnt < I_rd_hres - 1) & (V_cnt < I_rd_vres - 1);
assign Pout_hs_w = (H_cnt < I_h_res - 1) & (V_cnt < I_v_res - 1);
assign Pout_vs_w = (H_cnt < I_h_res - 1) & (V_cnt < I_v_res - 1);
assign Rden_w = (H_cnt < I_h_res - 1) & (V_cnt < I_v_res - 1);

assign O_rden = Rden_w;
assign O_de = Pout_de_w;
assign O_hs = Pout_hs_w & I_hs_pol;
assign O_vs = Pout_vs_w & I_vs_pol;

endmodule

