module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma, undersampled_sigma;
	reg [31:0] delta;
	wire [31:0] deriv;

	assign deriv = sigma - undersampled_sigma;
	assign dout = signed_data ? {deriv[31], deriv[30:0]} : deriv;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
		end else begin
			if (ock) begin
				if (sdi) sigma <= sigma + 1;
				else sigma <= sigma - 1;
			end
			if (uck) begin
				if (sdi) undersampled_sigma <= undersampled_sigma + 1;
				else undersampled_sigma <= undersampled_sigma - 1;
			end
		end
	end
endmodule

module RegFile(
