    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] RegFile [31:0];
    always @(negedge Clk) begin
        if (ReadReg1 != 0) begin
            ReadData1 <= RegFile[ReadReg1];
