            ReadData1 <= 0;
        end
        if (ReadReg2 != 0) begin
            ReadData2 <= RegFile[ReadReg2];
        end else begin
            ReadData2 <= 0;
        end
    end
    always @(posedge Clk) begin
        if (RegWrite) begin
            RegFile[WriteReg] <= WriteData;
        end
    end
endmodule

