module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg empty_n;
reg full_n;
reg [DEPTH_BITS-1:0] index;
reg [DATA_BITS-1:0] mem [0:DEPTH-1];

always @* begin
    empty_n = (index == 0);
    full_n  = (index == DEPTH-1);
    if (read && !empty_n) begin
        index <= index - 1;
    end
    if (write && !full_n) begin
        index <= index + 1;
    end
end

always @(posedge clk) begin
    if (aclr) begin
        empty_n <= 1;
        full_n  <= 0;
        index   <= 0;
    end else begin
        if (empty_n && write) begin
            mem[index] <= din;
            empty_n <= 0;
            full_n  <= 1;
        end
        if (full_n && read) begin
            empty_n <= 1;
            full_n  <= 0;
        end
    end
end

assign dout = mem[index];

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
); 

reg [31:0] timer;
reg pre;
  always @(posedge clk) begin
    if(timer == 32'd1000000) begin
      if(btn_input == pre) begin
        btn_output <= btn_input;
      end
      timer <= 0;
      pre <= btn_input;
    end
    else begin
      timer <= timer + 1;
    end
  end
endmodule

