module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);


input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
reg [DATA_WIDTH-1:0]            dout;
reg [DATA_WIDTH-1:0]            mem [2**ADDR_WIDTH-1:0];
reg [ADDR_WIDTH-1:0]            raddr_reg;
reg [ADDR_WIDTH-1:0]            waddr_reg;
reg                            re_reg;
reg                            we_reg;
reg                            bypass;

assign dout = (ENABLE_BYPASS && (raddr == waddr && re == we)) ? din : mem[raddr];

always @(posedge clk) begin
    if (rst) begin
        if (CLEAR_ON_INIT) begin
            mem <= {DATA_WIDTH{1'b0}};
        end
    end else begin
        if (we) begin
            mem[waddr] <= din;
        end
    end
end

always @(posedge clk) begin
    if (rst) begin
        raddr_reg <= 0;
        re_reg <= 0;
        we_reg <= 0;
        bypass <= 0;
    end else begin
        raddr_reg <= raddr;
        re_reg <= re;
        we_reg <= we;
        bypass <= (raddr == waddr && re == we);
    end
end

endmodule

