module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [1:0] state;
reg [23:0] r_count;
reg [23:0] r_size;

always @(posedge clk) begin
  if (rst) begin
    state <= IDLE;
    r_count <= 0;
    r_size <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (i_ppfifo_rdy[0]) begin
          state <= READY;
          r_count <= 0;
          r_size <= i_ppfifo_size;
        end
      end
      READY: begin
        if (i_h_blank) begin
          if (r_count == r_size) begin
            state <= RELEASE;
          end else begin
            r_count <= r_count + 1;
          end
        end else begin
          o_ppfifo_data <= i_rgb;
          o_ppfifo_stb <= 1;
        end
      end
      RELEASE: begin
        if (i_h_blank) begin
          state <= IDLE;
        end
      end
      default: begin
        state <= IDLE;
      end
    endcase
  end
end

assign o_ppfifo_clk = clk;
assign o_ppfifo_act = {i_ppfifo_rdy[1], i_ppfifo_rdy[0]};

endmodule

