module MEM_BLK_V5_0( clk,
                     write_en,
                     read_en,
                     wr_addr,
                     rd_addr,
                     data_in,
                     data_out,
                     rst
                   );


input                    clk;       
input                    write_en;    
input                    read_en ;
input  [(addr_value-1):0]  wr_addr;   
input  [(addr_value-1):0]  rd_addr;   
input  [(data_width-1):0]   data_in;   
input                    rst ;

output [(data_width-1):0]   data_out;
parameter data_width = 16;
parameter addr_value = 16;

reg [(data_width-1):0] mem [(addr_value-1):0];

