      fr2 <= 1'b0;
      fr1 <= 1'b1;
      fr0 <= 1'b1;
      dfr <= 1'b0;
    end else begin
      fr2 <= 1'b1;
      fr1 <= 1'b1;
      fr0 <= 1'b1;
      dfr <= 1'b0;
    end
  end
end

endmodule

module TopModule;
reg  d;
   reg  done_counting;
   reg  ack;
   reg  [9:0] state;
   wire B3_next;
   wire S_next;
   wire S1_next;
   wire Count_next;
   wire Wait_next;
   wire done;
   wire counting;
   wire shift_ena;

   assign B3_next = (state == 10'b1000000000);
   assign S_next = (state == 10'b0000000001);
   assign S1_next = (state == 10'b0000000010);
   assign Count_next = (state == 10'b1000000000);
   assign Wait_next = (state == 10'b0000000100);
   assign done = (done_counting == 1'b0) ? 1'b0 : (ack == 1'b0) ? 1'b0 : 1'b1;
   assign counting = (done_counting == 1'b0) ? 1'b0 : 1'b1;
   assign shift_ena = (ack == 1'b0) ? 1'b0 : 1'b1;

endmodule

module TopModule;
reg clk;
reg reset;
reg data;
reg done_counting;
reg ack;
reg shift_ena;
reg counting;
reg done;

always @(posedge clk) begin
    if (reset) begin
        shift_ena <= 0;
        counting <= 0;
        done <= 0;
    end else begin
        if (data == 1 && done_counting == 0) begin
            shift_ena <= 1;
            counting <= 0;
            done <= 0;
        end else if (shift_ena == 1) begin
            shift_ena <= 0;
            counting <= 1;
        end else if (counting == 1) begin
            if (done_counting == 1) begin
                counting <= 0;
                done <= 1;
            end
        end else if (done == 1) begin
            if (ack == 1) begin
                shift_ena <= 0;
                counting <= 0;
                done <= 0;
            end
        end
    end
end

endmodule

